import { ActionType, isGlobalPress, pressKeyFromArgs } from '@reticlehq/core';
import { asSyntheticInput } from './synthetic/synthetic-input.js';
import { nativeSetTimeout } from '../timers/native/native-timers.js';
const sleep = (ms) => new Promise((r) => nativeSetTimeout(r, ms));
import { isHtmlElement } from '../dom/realm.js';
function asString(value, fallback = '') {
    return 'string' === typeof value ? value : fallback;
}
export function pressKey(args) {
    return pressKeyFromArgs(args);
}
export function pressModifiers(args) {
    const raw = args['modifiers'];
    const names = Array.isArray(raw) ? raw.map((m) => asString(m).toLowerCase()) : [];
    const has = (...aliases) => aliases.some((a) => names.includes(a));
    return {
        metaKey: has('meta', 'cmd', 'command', 'super', 'win'),
        ctrlKey: has('control', 'ctrl'),
        shiftKey: has('shift'),
        altKey: has('alt', 'option', 'opt'),
    };
}
export function pressCode(args, key) {
    const explicit = args['code'];
    if ('string' === typeof explicit && 0 < explicit.length)
        return explicit;
    if (' ' === key)
        return 'Space';
    if (1 === key.length) {
        if (/[a-z]/i.test(key))
            return `Key${key.toUpperCase()}`;
        if (/[0-9]/.test(key))
            return `Digit${key}`;
        return '';
    }
    return /^[A-Z][A-Za-z0-9]*$/.test(key) && KNOWN_NAMED_KEYS.has(key) ? key : '';
}
const KNOWN_NAMED_KEYS = new Set([
    'Enter',
    'Escape',
    'Tab',
    'Backspace',
    'Delete',
    'Home',
    'End',
    'PageUp',
    'PageDown',
    'ArrowUp',
    'ArrowDown',
    'ArrowLeft',
    'ArrowRight',
    'Insert',
    'F1',
    'F2',
    'F3',
    'F4',
    'F5',
    'F6',
    'F7',
    'F8',
    'F9',
    'F10',
    'F11',
    'F12',
]);
const NO_DOCUMENT_TO_PRESS = 'no document to press into';
export function focusedOrDocument() {
    const active = document.activeElement;
    if (isHtmlElement(active) && document.body !== active)
        return active;
    if (isHtmlElement(document.body))
        return document.body;
    const root = document.documentElement;
    if (isHtmlElement(root))
        return root;
    throw new Error(NO_DOCUMENT_TO_PRESS);
}
export function isReflessDocumentPress(ref, action, args) {
    return 0 === ref.length && isGlobalPress(args) && ActionType.PRESS === action;
}
export function pressKeys(args) {
    const raw = args['keys'];
    if (!Array.isArray(raw))
        return [];
    return raw.map((k) => asString(k)).filter((k) => k.length > 0);
}
const KEY_REPEAT_MS = 33;
const KEY_REPEAT_DELAY_MS = 500;
export async function holdKey(el, key, code, mods, ms) {
    const started = Date.now();
    if (ms > KEY_REPEAT_DELAY_MS)
        await sleep(KEY_REPEAT_DELAY_MS);
    while (Date.now() - started < ms) {
        asSyntheticInput(() => el.dispatchEvent(new KeyboardEvent('keydown', {
            key,
            code,
            bubbles: true,
            cancelable: true,
            repeat: true,
            ...mods,
        })));
        await sleep(Math.min(KEY_REPEAT_MS, Math.max(0, ms - (Date.now() - started))));
    }
}
export async function pressCombo(el, keys, mods, holdMs) {
    let prevented = false;
    for (const key of keys) {
        const code = pressCode({}, key);
        const ok = asSyntheticInput(() => el.dispatchEvent(new KeyboardEvent('keydown', { key, code, bubbles: true, cancelable: true, ...mods })));
        if (!ok)
            prevented = true;
    }
    if (holdMs > 0)
        await sleep(holdMs);
    for (const key of [...keys].reverse()) {
        const code = pressCode({}, key);
        asSyntheticInput(() => el.dispatchEvent(new KeyboardEvent('keyup', { key, code, bubbles: true, ...mods })));
    }
    return prevented;
}
export const ZOOM_NEEDS_REAL_BROWSER_MSG = 'cannot zoom from inside the page — CSS zoom changes how it LOOKS without changing the layout ' +
    'viewport, visualViewport or media queries, so a layout that breaks at 200% would be reported as ' +
    'checked and passing. Drive a real browser (reticle drive <url>, or reticle_lease) and zoom there.';
